'use strict';
let joystickEnabled=true;try{joystickEnabled=localStorage.getItem('zenwreath-joystick')!=='off'}catch(e){}
function applyControlChoice(){document.body.classList.toggle('tap-controls',!joystickEnabled);$('joystick').setAttribute('aria-hidden',String(!joystickEnabled));$('game').setAttribute('aria-label',joystickEnabled?'Move with the joystick, tap the ground, or use arrow keys. Tap the nearby action button to interact.':'Tap a clear patch of ground to walk. Tap the nearby action button to interact. Arrow keys also work.');resetInput();resizeGame()}
function changeDifficulty(value){if(value==='peaceful'&&team.room){lobby();status('Leave the shared room to choose Peaceful difficulty. Your solo quest will be restored.');return false}gentlePlay=value==='peaceful';try{localStorage.setItem('zenwreath-gentle',gentlePlay?'1':'0')}catch(e){}if(gentlePlay&&s)s.player.hp=maxHealth();applyGentleUI();applyControlChoice();save();update();return true}
function playSettings(){appDialog('play-settings','DIFFICULTY & CONTROLS','Play your way.','Changes save on this phone. Your current quest stays.',[['Back to game',returnToGame,true],['Wide-screen play',wideScreenPlay],['More settings',()=>{if(gentleMode()){appDialog('options','MORE SETTINGS','Your game settings.','Choose what to adjust.',[['Sound',()=>audioSettings(playSettings),true],['Export save',exportSave],['Import save',()=>$('file').click()],['Back',playSettings]])}else everydaySettings()}]],'<div class="controlChoices"><label>Difficulty<select id="playDifficulty"><option value="peaceful">Peaceful — no heart loss</option><option value="hard">Hard · stronger, faster enemies</option><option value="medium">Medium · balanced adventure</option></select></label><p class="settingsHint">Peaceful has no countdown and uses a simpler menu. Medium has gentler battles; Hard has stronger enemies and faster attacks. All modes keep your progress when you fall.</p><label>Movement<select id="playMovement"><option value="joystick">Joystick + tap to move</option><option value="tap">Tap to move — hide joystick</option></select></label><p class="settingsHint">Tap clear ground to walk there. Rotate your phone sideways for horizontal play, or keep it upright. Wide-screen play requests fullscreen where available.</p></div><p id="playSettingsStatus" class="small" role="status"></p>');$('playDifficulty').value=typeof difficultyValue==='function'?difficultyValue():gentleMode()?'peaceful':'standard';$('playMovement').value=joystickEnabled?'joystick':'tap';$('playDifficulty').onchange=()=>{if(changeDifficulty($('playDifficulty').value)){$('playSettingsStatus').textContent='Difficulty saved.'}};$('playMovement').onchange=()=>{joystickEnabled=$('playMovement').value==='joystick';try{localStorage.setItem('zenwreath-joystick',joystickEnabled?'on':'off')}catch(e){}applyControlChoice();$('playSettingsStatus').textContent='Movement saved.'}}
async function wideScreenPlay(){try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();if(screen.orientation?.lock)try{await screen.orientation.lock('landscape')}catch(e){}returnToGame();resizeGame();toast('Turn your phone sideways for horizontal play.')}catch(e){$('playSettingsStatus').textContent='Rotate your phone sideways. If needed, turn on Auto-rotate in your phone settings.'}}
window.addEventListener('orientationchange',()=>{resetInput();requestAnimationFrame(resizeGame)});document.addEventListener('fullscreenchange',()=>{resetInput();resizeGame()});applyControlChoice();
